82. 	if err != nil {
83. 		return err
84. 	}
85. 	var (
86. 		nerdctlArgs, envs, fileEnvs []string
87. 		skip                        bool
88. 	)
89. 
90. 	for i, arg := range args {
91. 		// parsing environment values from the command line may pre-fetch and
92. 		// consume the next argument; this loop variable will skip these pre-consumed
93. 		// entries from the command line
94. 		if skip {
95. 			skip = false
96. 			continue
97. 		}
98. 		switch {
99. 		case arg == "--debug":
100. 			// explicitly setting log level to avoid `--debug` flag being interpreted as nerdctl command
101. 			nc.logger.SetLevel(flog.Debug)
102. 		case argIsEnv(arg):
103. 			shouldSkip, addEnv := handleEnv(nc.systemDeps, arg, args[i+1])
104. 			skip = shouldSkip
105. 			if addEnv != "" {
106. 				envs = append(envs, addEnv)
107. 			}
108. 		case strings.HasPrefix(arg, "--env-file"):
109. 			shouldSkip, addEnvs, err := handleEnvFile(nc.fs, nc.systemDeps, arg, args[i+1])
110. 			if err != nil {
111. 				return err
112. 			}
113. 			skip = shouldSkip
114. 			fileEnvs = append(fileEnvs, addEnvs...)
115. 		case strings.HasPrefix(arg, "--add-host"):
116. 			switch arg {
117. 			case "--add-host":
118. 				args[i+1] = resolveIP(args[i+1], nc.logger)
119. 			default:
120. 				resolvedIP := resolveIP(arg[11:], nc.logger)
121. 				arg = fmt.Sprintf("%s%s", arg[0:11], resolvedIP)
122. 			}
123. 			nerdctlArgs = append(nerdctlArgs, arg)
124. 		default:
125. 			nerdctlArgs = append(nerdctlArgs, arg)
126. 		}
127. 	}
128. 	// to handle environment variables properly, we add all entries found via
129. 	// env-file includes to the map first and then all command line environment
130. 	// flags, making sure that command line overrides environment file options,
131. 	// and that later command line flags override earlier ones
132. 	envVars := make(map[string]string)
133. 
134. 	for _, e := range fileEnvs {
135. 		evar, eval, _ := strings.Cut(e, "=")
136. 		envVars[evar] = eval
137. 	}
138. 	for _, e := range envs {
139. 		evar, eval, _ := strings.Cut(e, "=")
140. 		envVars[evar] = eval
141. 	}
142. 
143. 	passedEnvs := []string{"COSIGN_PASSWORD"}
144. 	var passedEnvArgs []string
145. 	for _, e := range passedEnvs {
146. 		v, b := nc.systemDeps.LookupEnv(e)
147. 		if b {
148. 			passedEnvArgs = append(passedEnvArgs, fmt.Sprintf("%s=%s", e, v))
149. 		}
150. 	}
151. 
152. 	// Add -E to sudo command in order to preserve existing environment variables, more info:
153. 	// https://stackoverflow.com/questions/8633461/how-to-keep-environment-variables-when-using-sudo/8633575#8633575
154. 	limaArgs := append([]string{"shell", limaInstanceName, "sudo", "-E"}, passedEnvArgs...)
155. 
156. 	limaArgs = append(limaArgs, []string{nerdctlCmdName, cmdName}...)
157. 
158. 	var finalArgs []string
159. 	for key, val := range envVars {
160. 		finalArgs = append(finalArgs, "-e", fmt.Sprintf("%s=%s", key, val))
161. 	}
162. 	finalArgs = append(finalArgs, nerdctlArgs...)
163. 	// Add -E to sudo command in order to preserve existing environment variables, more info:
164. 	// https://stackoverflow.com/questions/8633461/how-to-keep-environment-variables-when-using-sudo/8633575#8633575
165. 	limaArgs = append(limaArgs, finalArgs...)
166. 
167. 	if nc.shouldReplaceForHelp(cmdName, args) {
168. 		return nc.creator.RunWithReplacingStdout([]command.Replacement{{Source: "nerdctl", Target: "finch"}}, limaArgs...)
169. 	}
170. 
171. 	return nc.creator.Create(limaArgs...).Run()
