174. func (nc *nerdctlCommand) assertVMIsRunning(creator command.LimaCmdCreator, logger flog.Logger) error {
175. 	// Extra call to check VM before running nerdctl commands. These are the reasons of not doing message replacing
176. 	// 1. for the non-help commands, replacing stdout may cause "stdin is not a terminal" error for the commands that need input.
177. 	// E.g. finch login.
178. 	// 2. an extra call could give us more control about the error messages. Message replacing may fail if upstream
179. 	// changes the format of source string, which leads to extra CI validation work.
180. 	status, err := lima.GetVMStatus(creator, logger, limaInstanceName)
181. 	if err != nil {
182. 		return err
183. 	}
184. 	switch status {
185. 	case lima.Nonexistent:
186. 		return fmt.Errorf("instance %q does not exist, run `finch %s init` to create a new instance",
187. 			limaInstanceName, virtualMachineRootCmd)
188. 	case lima.Stopped:
189. 		return fmt.Errorf("instance %q is stopped, run `finch %s start` to start the instance",
190. 			limaInstanceName, virtualMachineRootCmd)
191. 	default:
192. 		return nil
193. 	}
194. }
