36. // PlatformData defines the YAML structure for the platform data included in a support bundle.
37. type PlatformData struct {
38. 	Os    string `yaml:"os"`
39. 	Arch  string `yaml:"arch"`
40. 	Finch string `yaml:"finch"`
41. }
