56. // NewBundleBuilder produces a new BundleBuilder.
57. func NewBundleBuilder(
58. 	logger flog.Logger,
59. 	fs afero.Fs,
60. 	config BundleConfig,
61. 	finch fpath.Finch,
62. 	ecc command.Creator,
63. ) BundleBuilder {
64. 	return &bundleBuilder{
65. 		logger: logger,
66. 		fs:     fs,
67. 		config: config,
68. 		finch:  finch,
69. 		ecc:    ecc,
70. 	}
71. }
