73. // GenerateSupportBundle generates a new support bundle.
74. func (bb *bundleBuilder) GenerateSupportBundle(additionalFiles []string, excludeFiles []string) (string, error) {
75. 	zipFileName := bundleFileName()
76. 	bb.logger.Debugf("Creating %s...", zipFileName)
77. 	zipFile, err := bb.fs.Create(zipFileName)
78. 	if err != nil {
79. 		return "", err
80. 	}
81. 
82. 	zipPrefix := strings.TrimSuffix(zipFileName, path.Ext(zipFileName))
83. 
84. 	writer := zip.NewWriter(zipFile)
85. 
86. 	_, err = writer.Create(fmt.Sprintf("%s/", zipPrefix))
87. 	if err != nil {
88. 		return "", err
89. 	}
90. 
91. 	platform, err := bb.getPlatformData()
92. 	if err != nil {
93. 		return "", err
94. 	}
95. 
96. 	bb.logger.Debugln("Gathering platform data...")
97. 	err = writePlatformData(writer, platform, zipPrefix)
98. 	if err != nil {
99. 		return "", err
100. 	}
101. 
102. 	bb.logger.Debugln("Copying in log files...")
103. 	for _, file := range bb.config.LogFiles() {
104. 		if fileShouldBeExcluded(file, excludeFiles) {
105. 			bb.logger.Infof("Excluding %s...", file)
106. 			continue
107. 		}
108. 		err := bb.copyInFile(writer, file, path.Join(zipPrefix, logPrefix))
109. 		if err != nil {
110. 			bb.logger.Warnf("Could not copy in %q. Error: %s", file, err)
111. 		}
112. 	}
113. 
114. 	bb.logger.Debugln("Copying in config files...")
115. 	for _, file := range bb.config.ConfigFiles() {
116. 		if fileShouldBeExcluded(file, excludeFiles) {
117. 			bb.logger.Infof("Excluding %s...", file)
118. 			continue
119. 		}
120. 		err := bb.copyInFile(writer, file, path.Join(zipPrefix, configPrefix))
121. 		if err != nil {
122. 			bb.logger.Warnf("Could not copy in %q. Error: %s", file, err)
123. 		}
124. 	}
125. 
126. 	bb.logger.Debugln("Copying in additional files...")
127. 	for _, file := range additionalFiles {
128. 		if fileShouldBeExcluded(file, excludeFiles) {
129. 			bb.logger.Infof("Excluding %s...", file)
130. 			continue
131. 		}
132. 		err := bb.copyInFile(writer, file, path.Join(zipPrefix, additionalPrefix))
133. 		if err != nil {
134. 			bb.logger.Warnf("Could not add additional file %s. Error: %s", file, err)
135. 		}
136. 	}
137. 
138. 	err = writer.Close()
139. 	if err != nil {
140. 		return "", err
141. 	}
142. 
143. 	return zipFileName, nil
144. }
