146. func (bb *bundleBuilder) copyInFile(writer *zip.Writer, fileName string, prefix string) error {
147. 	f, err := bb.fs.Open(fileName)
148. 	if err != nil {
149. 		return err
150. 	}
151. 
152. 	bb.logger.Debugf("Copying %s...", fileName)
