 	for _, e := range envs {
 		evar, eval, _ := strings.Cut(e, "=")
 		envVars[evar] = eval
 	}

 	passedEnvs := []string{"COSIGN_PASSWORD"}
 	var passedEnvArgs []string
 	for _, e := range passedEnvs {
 		v, b := nc.systemDeps.LookupEnv(e)
 		if b {
 			passedEnvArgs = append(passedEnvArgs, fmt.Sprintf("%s=%s", e, v))
