29. 	bundlePrefix     = "finch-support"
30. 	platformFileName = "platform.yaml"
31. 	logPrefix        = "logs"
32. 	configPrefix     = "configs"
33. 	additionalPrefix = "misc"
34. )
35. 
36. // PlatformData defines the YAML structure for the platform data included in a support bundle.
37. type PlatformData struct {
38. 	Os    string `yaml:"os"`
39. 	Arch  string `yaml:"arch"`
40. 	Finch string `yaml:"finch"`
41. }
42. 
43. // BundleBuilder provides methods to generate support bundles.
44. type BundleBuilder interface {
45. 	GenerateSupportBundle([]string, []string) (string, error)
46. }
47. 
48. type bundleBuilder struct {
49. 	logger flog.Logger
50. 	fs     afero.Fs
51. 	config BundleConfig
52. 	finch  fpath.Finch
53. 	ecc    command.Creator
54. }
55. 
56. // NewBundleBuilder produces a new BundleBuilder.
57. func NewBundleBuilder(
58. 	logger flog.Logger,
59. 	fs afero.Fs,
60. 	config BundleConfig,
61. 	finch fpath.Finch,
62. 	ecc command.Creator,
63. ) BundleBuilder {
64. 	return &bundleBuilder{
65. 		logger: logger,
66. 		fs:     fs,
67. 		config: config,
68. 		finch:  finch,
69. 		ecc:    ecc,
70. 	}
71. }
