204. func (bb *bundleBuilder) getPlatformData() (*PlatformData, error) {
205. 	platform := &PlatformData{}
206. 
207. 	// populate OS version
208. 	os, err := bb.getOSVersion()
209. 	if err != nil {
210. 		return nil, err
211. 	}
212. 	platform.Os = os
213. 
214. 	// populate arch
215. 	arch, err := bb.getArch()
216. 	if err != nil {
217. 		return nil, err
218. 	}
219. 	platform.Arch = arch
