 func fileShouldBeExcluded(filename string, exclude []string) bool {
 	fileAbs, err := filepath.Abs(filename)
 	if err != nil {
 		return true
 	}
 	for _, excludeFile := range exclude {
 		excludeAbs, err := filepath.Abs(excludeFile)
 		if err != nil {
